#!/usr/bin/env tsx
/**
 * @file packages/protocol/scripts/gen-commands-doc.ts
 * Generates `docs/engine/commands.md` from the COMMANDS registry (§8.8):
 * one table per family with columns Command · Syntax · Flags · Summary.
 * Run with `pnpm docs:commands` (= `pnpm --filter @downstash/protocol gen:docs`).
 * CI fails if the regenerated file differs (`git diff --exit-code`).
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { COMMANDS } from '../src/commands.ts';
import type { CommandFamily } from '../src/types.ts';

const here = path.dirname(fileURLToPath(import.meta.url));
const outPath = path.resolve(here, '..', '..', '..', 'docs', 'engine', 'commands.md');

const FAMILY_ORDER: CommandFamily[] = [
  'strings',
  'keyspace',
  'hashes',
  'lists',
  'sets',
  'zsets',
  'server',
  'scripting'
];

const FAMILY_TITLE: Record<CommandFamily, string> = {
  strings: 'Strings',
  keyspace: 'Keyspace & expiry',
  hashes: 'Hashes',
  lists: 'Lists',
  sets: 'Sets',
  zsets: 'Sorted sets',
  server: 'Server',
  scripting: 'Scripting'
};

/** Render flags as the SQL registry does: `write`, `read,cacheable`, etc. */
function flagsCell(flags: readonly string[]): string {
  return `\`{${flags.join(',')}}\``;
}

function familyTable(family: CommandFamily): string {
  const rows = Object.values(COMMANDS)
    .filter((c) => c.family === family)
    .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    .map((c) => `| ${c.name} | ${c.syntax} | ${flagsCell(c.flags)} | ${c.summary} |`);
  return [
    `## ${FAMILY_TITLE[family]}`,
    '',
    '| Command | Syntax | Flags | Summary |',
    '|---------|--------|-------|---------|',
    ...rows,
    ''
  ].join('\n');
}

function main(): void {
  const total = Object.keys(COMMANDS).length;
  const body = [
    '<!-- GENERATED by pnpm docs:commands. DO NOT EDIT. -->',
    '',
    '# Command reference',
    '',
    `Generated from \`packages/protocol/src\` (\`COMMANDS\`). ${total} commands across ${FAMILY_ORDER.length} families.`,
    'The SQL `downstash.command_registry` and this table are kept identical;',
    '`tests/sql/registry-parity.test.ts` enforces it.',
    '',
    ...FAMILY_ORDER.map(familyTable)
  ].join('\n');

  mkdirSync(path.dirname(outPath), { recursive: true });
  writeFileSync(outPath, body, 'utf8');
  process.stdout.write(
    `wrote ${path.relative(process.cwd(), outPath)} (${total} commands)\n`
  );
}

main();
